    public static function getDataEmailAcountWebklex($emailaccount_id, $lastUid = null, $maxItems = 100)
    {
        try {
            $mail_account = EmailAccountPeer::retrieveByPK($emailaccount_id);
            //*******************************************************************************************
            if($mail_account == null){
                return null;
            }
            //*******************************************************************************************
            $eproviderconfig_id = $mail_account->getEmailproviderconfigId();
            $usuarioaccount_id = $mail_account->getusuarioId();
            //*******************************************************************************************
            if($eproviderconfig_id === null){
                return null;
            }
            //*******************************************************************************************
            $eprovider_config = EmailProviderConfigPeer::retrieveByPK($eproviderconfig_id);
            $host_smtp = $eprovider_config->getServerName();
            $port_listen = $eprovider_config->getListenPuerto();
            $encryption_listen = $eprovider_config->getTypeEncryption();
            $email_provider = EmailProviderPeer::retrieveByPK($eprovider_config->getEmailproviderId());
            //*******************************************************************************************
            // IMAP genérico
            if($email_provider->getEmailtipoauthId() == EmailTypeAuth::Password) {
                if($email_provider->getPrimaryKey() == EmailProviders::Imap){
                    $exchange = new ImapAccess($host_smtp, $port_listen, $encryption_listen);
                    $exchange->authenticate([
                        'username' => $mail_account->getAccountLogin(),
                        'password' => SED::decryption($mail_account->getAccountPass())
                    ]);
                }
            }else if($email_provider->getEmailtipoauthId() == EmailTypeAuth::OAuth){
                if($email_provider->getPrimaryKey() == EmailProviders::Outlook){
                    $settings['client_id'] = $eprovider_config->getOauth2Client();
                    $settings['tenant_id'] = $eprovider_config->getTenantName();
                    $settings['client_secret'] = SED::decryption($eprovider_config->getOauth2Secret());
                    $settings['redirect_uri'] = $eprovider_config->getOauth2RedirectUri();
                    $settings['host_name'] = $host_smtp;
                    $settings['port_listen'] = $port_listen;
                    $settings['encryption_listen'] = $encryption_listen;
                    $settings['encryption_listen'] = $encryption_listen;
                    $settings['username'] = $mail_account->getAccountLogin();

                    $exchange = new OutlookProvider($settings);
                    $exchange->authenticate([
                        'username' => $mail_account->getAccountLogin(),
                        'password' => SED::decryption($mail_account->getAccountPass()),
                        'code' => $exchange->accessToken,
                        'code_refresh' => $exchange->refreshToken
                    ]);
                }else if($email_provider->getPrimaryKey() == EmailProviders::Gmail){
                    $exchange = new GmailProvider($host_smtp, $port_listen, $encryption_listen);
                    $exchange->authenticate([
                        'username' => $mail_account->getAccountLogin(),
                        'password' => SED::decryption($mail_account->getAccountPass())
                    ]);
                }else{
                    return false;
                }
            }else{
                return false;
            }
            //*******************************************************************************************
            $list_emails = $exchange->getEmails($maxItems,$lastUid);
            //*******************************************************************************************
            if(count($list_emails)){ 
                $mail_account->setLastSyncData(date("Y-m-d G:i:s"));
                $mail_account->save();
            }
            //*******************************************************************************************
            foreach ($list_emails as $email) {
                try{
                    $isMsgProcess = EmailTrackingPeer::isMessageProcessed($email['message_id'], $mail_account->getAccountLogin());
                    if($isMsgProcess){
                        continue;
                    }
                    //***********************************************************************************
                    $email_obj = new Email();
                    $email_obj->setEmailAccountId($mail_account->getPrimaryKey());
                    $email_obj->setEmailestadoId(EmailStatus::Descargado);
                    $email_obj->setMessageId($email['message_id']);
                    $email_obj->setEmailOrigen($email['from_email']);
                    $email_obj->setEmailDestino($email['to_email']);
                    $email_obj->setAsunto($email['subject']);
                    $email_obj->setCountAttachment(count($email['attachments']));
                    $email_obj->setContenido($email['body']);
                    //***********************************************************************************
                    if(empty(trim($email['clean_html']))){
                        $email_obj->setBodyClean(null);
                    }else{
                        $email_obj->setBodyClean(trim($email['clean_html']));
                    }
                    //***********************************************************************************
                    $email_obj->setEmailCopia($email['cc_email']);
                    $email_obj->setFechaRecibido($email['date_received']);
                    $email_obj->setFechaCreacion(date("Y-m-d G:i:s"));
                    $email_obj->setFechaModificacion(date("Y-m-d G:i:s"));                
                    $email_obj->save();
                } catch (PropelException $th) {
                    $email_obj = null;
                } catch (\Exception $th) {
                    $email_obj = null;
                } catch(\Throwable $th){
                    $email_obj = null;
                }
                //***************************************************************************************
                if($email_obj == null){
                    $isProcesado = EmailPeer::isProcesesEmail($email['message_id'], $mail_account->getAccountLogin());
                    if($isProcesado){
                        EmailTrackingPeer::addProccesedMessageUid($mail_account->getPrimaryKey(),$email['message_id'],$email['message_uid']);
                    }
                    //***********************************************************************************
                    continue;
                }else{
                    EmailBitacoraPeer::addBitacoraByEmailId($email_obj->getPrimaryKey(),$usuarioaccount_id);
                    EmailTrackingPeer::addProccesedMessageUid($mail_account->getPrimaryKey(),$email['message_id'],$email['message_uid']);    
                }
                //***************************************************************************************
                EmailPeer::processAttachmentByEmail($email,$email_obj,$exchange,$usuarioaccount_id);
            }
            //*******************************************************************************************
            $last_uid = $exchange->getMaxUid($list_emails);
            EmailAccountSyncPeer::addOrUpdateLastMessageUid($mail_account->getPrimaryKey(), $mail_account->getAccountLogin(),$last_uid);
        } catch (PropelException $th) {
            return false;
        } catch (\Exception $th) {
            return false;
        } catch (\Throwable $th) {
            return false;
        }
    }

