    public static function isProcesesEmail($message_id = 0, $account_login = null)
    {
        try{
            $c = new Criteria();
            $c->addJoin(EmailPeer::EMAILACCOUNT_ID,EmailAccountPeer::EMAILACCOUNT_ID, Criteria::INNER_JOIN);
            //*******************************************************************************************
            $c->add(EmailPeer::MESSAGE_ID,$message_id);
            $c->add(EmailAccountPeer::ACCOUNT_LOGIN,$account_login);
            //*******************************************************************************************
            return EmailPeer::doCount($c) > 0 ? true : false;
        } catch (PropelException $th) {
            return false;
        } catch (\Exception $th) {
            return false;
        } catch (\Throwable $th) {
            return false;
        }
    }

